import java.util.Scanner;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class Main {
    static Scanner scanner = new Scanner(System.in);

    public static void main(String[] args) {
        int n = readInt();
        System.out.print(3 * n / 2);
    }

    static int readInt() {
        return scanner.nextInt();
    }

    static long readLong() {
        return scanner.nextLong();
    }

    static List<Integer> readInts() {
        return Arrays.stream(scanner.nextLine().split(" ")).map(Integer::parseInt).collect(Collectors.toList());
    }

    static List<Long> readLongs() {
        return Arrays.stream(scanner.nextLine().split(" ")).map(Long::parseLong).collect(Collectors.toList());
    }
}

